constexpr double EPS = 1e-7;
constexpr ll INF = 1e9;
constexpr double PI = acos(-1);
constexpr ll MOD = 1000000007;

ll N, K;

template<typename T>
class Matrix {
private:
    vector<vector<T>> data;

public:
    Matrix() = default;

    Matrix(size_t rows, size_t cols) : data(rows, vector<T>(cols, 0)) {}

    Matrix(size_t n) : data(n, vector<T>(n, 0)) {}

    size_t rows() const { return data.size(); }
    size_t cols() const { return data.empty() ? 0 : data[0].size(); }

    const vector<T>& operator[](int idx) const { return data.at(idx); }
    vector<T>& operator[](int idx) { return data.at(idx); }

    static Matrix identity(size_t n) {
        Matrix mat(n);
        for (size_t i = 0; i < n; ++i) mat[i][i] = 1;
        return mat;
    }

    Matrix& operator+=(const Matrix& other) {
        assert(rows() == other.rows() && cols() == other.cols());
        for (size_t i = 0; i < rows(); ++i)
            for (size_t j = 0; j < cols(); ++j)
                data[i][j] = (data[i][j] + other[i][j]) % MOD;
        return *this;
    }

    Matrix& operator-=(const Matrix& other) {
        assert(rows() == other.rows() && cols() == other.cols());
        for (size_t i = 0; i < rows(); ++i)
            for (size_t j = 0; j < cols(); ++j)
                data[i][j] = (data[i][j] - other[i][j] + MOD) % MOD;
        return *this;
    }

    Matrix& operator*=(const Matrix& other) {
        size_t n = rows(), m = other.cols(), p = cols();
        assert(p == other.rows());
        vector<vector<T>> result(n, vector<T>(m, 0));
        for (size_t i = 0; i < n; ++i)
            for (size_t j = 0; j < m; ++j)
                for (size_t k = 0; k < p; ++k)
                    result[i][j] = (result[i][j] + data[i][k] * other[k][j]) % MOD;
        data.swap(result);
        return *this;
    }

    Matrix& operator^=(ll exponent) {
        Matrix result = Matrix::identity(rows());
        Matrix base = *this;
        while (exponent > 0) {
            if (exponent & 1) result *= base;
            base *= base;
            exponent >>= 1;
        }
        data.swap(result.data);
        return *this;
    }

    Matrix operator+(const Matrix& other) const { return Matrix(*this) += other; }
    Matrix operator-(const Matrix& other) const { return Matrix(*this) -= other; }
    Matrix operator*(const Matrix& other) const { return Matrix(*this) *= other; }
    Matrix operator^(ll exponent) const { return Matrix(*this) ^= exponent; }

    friend ostream& operator<<(ostream& os, const Matrix& m) {
        for (size_t i = 0; i < m.rows(); ++i) {
            os << "[";
            for (size_t j = 0; j < m.cols(); ++j) {
                os << m[i][j] << (j + 1 == m.cols() ? "]\n" : ",");
            }
        }
        return os;
    }

    T det() {
        Matrix copy = *this;
        assert(rows() == cols());
        T determinant = 1;
        size_t n = rows();
        for (size_t i = 0; i < n; ++i) {
            int pivot = -1;
            for (size_t j = i; j < n; ++j) {
                if (copy[j][i] != 0) {
                    pivot = j;
                    break;
                }
            }
            if (pivot == -1) return 0;
            if (i != pivot) {
                determinant = (determinant * (MOD - 1)) % MOD;
                swap(copy[i], copy[pivot]);
            }
            determinant = (determinant * copy[i][i]) % MOD;
            T inv = mod_inverse(copy[i][i], MOD);
            for (size_t j = 0; j < n; ++j) {
                copy[i][j] = (copy[i][j] * inv) % MOD;
            }
            for (size_t j = i + 1; j < n; ++j) {
                T factor = copy[j][i];
                for (size_t k = 0; k < n; ++k) {
                    copy[j][k] = (copy[j][k] - copy[i][k] * factor) % MOD;
                    if (copy[j][k] < 0) copy[j][k] += MOD;
                }
            }
        }
        return (determinant + MOD) % MOD;
    }

private:
    T mod_inverse(T a, T mod) {
        T m0 = mod, y = 0, x = 1;
        if (mod == 1) return 0;
        while (a > 1) {
            T q = a / mod;
            T t = mod;
            mod = a % mod;
            a = t;
            t = y;
            y = x - q * y;
            x = t;
        }
        if (x < 0) x += m0;
        return x;
    }

public:
    void rotate() {
        Matrix<T> temp(rows());
        for (size_t i = 0; i < K; ++i) {
            for (size_t j = 0; j < K; ++j) {
                temp[i][j] = data[(i + K - 1) % K][(j + K - 1) % K];
            }
            temp[i][K] = data[(i + K - 1) % K][K];
            temp[K][i] = data[K][(i + K - 1) % K];
        }
        temp[K][K] = data[K][K];
        data = temp.data;
    }
};

Matrix<ll> mat[70][35];

ll power(ll base, ll exp) {
    if (exp == 0) return 1;
    ll result = power(base, exp / 2);
    result = (result * result) % MOD;
    if (exp & 1) result = (result * base) % MOD;
    return result;
}

