    while (temp >= K) {
        depth++;
        temp /= K;
    }

    mat[0][0] = Matrix<ll>::identity(K + 1);
    for (int i = 1; i < K + 1; ++i) mat[0][0][0][i] = 1;

    for (int i = 1; i < K; ++i) {
        mat[0][i] = mat[0][i-1];
        mat[0][i].rotate();
    }

    for (ll idx = 1; idx <= depth; ++idx) {
        mat[idx][0] = mat[idx-1][0];
        for (int i = 1; i < K; ++i) {
            mat[idx][0] = mat[idx-1][i] * mat[idx][0];
        }
        for (int i = 1; i < K; ++i) {
            mat[idx][i] = mat[idx][i-1];
            mat[idx][i].rotate();
        }
    }

    Matrix<ll> result(K + 1, 1);
    result[K][0] = 1;
    int offset = 0;

    while (depth >= 0) {
        for (int i = 0; ; ++i) {
            if (power(K, depth) <= N) {
                N -= power(K, depth);
                result = mat[depth][offset] * result;
                offset = (offset + 1) % K;
            } else {
                break;
            }
        }
        depth--;
    }

    ll sum = 0;
    for (int i = 0; i < K + 1; ++i) {
        sum = (sum + result[i][0]) % MOD;
    }
    cout << sum << '\n';

    return 0;
}
